window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-173e1d2c3c87aaf0"]={"versions": [{"id": "FIG-173e1d2c3c87aaf0", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR ECU Resource Template (ResourceTemplateECU). Es modelliert die Vererbungshierarchie und Parametrisierung von Peripheriemodulen zur Pulsweitenverarbeitung (Pulsweitenmodulation und Pulsweitenerfassung) auf Hardware- bzw. Mikrocontrollerebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassenelemente und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>PulseWidthPeripheral</code> (stereotypisiert als <code>«Peripheral»</code>, abstrakt formatiert): Basisklasse für pulsweitenbezogene Peripherien mit dem Attribut:\n<ul class=\"fig-list\"><li><code>+ resolution: Int</code>: Auflösung des Peripheriemoduls als Integer.\n</li></ul>\n</li><li><code>PWM</code>: Spezialisierung von <code>PulseWidthPeripheral</code> zur Pulsweitenmodulation ohne eigene zusätzliche Attribute.\n</li><li><code>PWD</code>: Spezialisierung von <code>PulseWidthPeripheral</code> zur Pulsweitenerfassung (Pulse Width Demodulation / Detection) mit den Attributen:\n<ul class=\"fig-list\"><li><code>+ phaseDetection: Boolean</code>: Flag zur Aktivierung der Phasendetektion.\n</li><li><code>+ mode: Enumeration{twoPhaseInput, threePhaseInput}</code>: Betriebsmodusauswahl zwischen Zweiphasen- und Dreiphasen-Eingang.\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Beide Subklassen erben über eine Generalisierungsbeziehung (Pfeil mit geschlossener, nicht ausgefüllter Spitze) von <code>PulseWidthPeripheral</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Darstellung von dynamischem Laufzeitverhalten, Zustandsübergängen oder Sequenzabläufen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevant für die formale Hardware-Ressourcenbeschreibung im AUTOSAR ECU Resource Template. Die Attribute legen die Konfigurations- und Modellierungsanforderungen für Hardware-Peripherieelemente des Typs PWM und PWD fest. Für <code>PWD</code> sind zwingend die Konfigurationsparameter für Phasenüberwachung (<code>phaseDetection</code>) und der Enumerationswert <code>mode</code> bereitzustellen, während beide Modultypen die Basiseigenschaft <code>resolution</code> erben.</p>"}, {"id": "FIG-16a4d5ca14796420", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR ECU Resource Template (ResourceTemplateECU). Es modelliert die Vererbungshierarchie und Parametrisierung von Peripheriemodulen zur Pulsweitenverarbeitung (Pulsweitenmodulation und Pulsweitenerfassung) auf Hardware- bzw. Mikrocontrollerebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassenelemente und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>PulseWidthPeripheral</code> (stereotypisiert als <code>«Peripheral»</code>, abstrakt formatiert): Basisklasse für pulsweitenbezogene Peripherien mit dem Attribut:\n<ul class=\"fig-list\"><li><code>+ resolution: Int</code>: Auflösung des Peripheriemoduls als Integer.\n</li></ul>\n</li><li><code>PWM</code>: Spezialisierung von <code>PulseWidthPeripheral</code> zur Pulsweitenmodulation ohne eigene zusätzliche Attribute.\n</li><li><code>PWD</code>: Spezialisierung von <code>PulseWidthPeripheral</code> zur Pulsweitenerfassung (Pulse Width Demodulation / Detection) mit den Attributen:\n<ul class=\"fig-list\"><li><code>+ phaseDetection: Boolean</code>: Flag zur Aktivierung der Phasendetektion.\n</li><li><code>+ mode: Enumeration{twoPhaseInput, threePhaseInput}</code>: Betriebsmodusauswahl zwischen Zweiphasen- und Dreiphasen-Eingang.\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Beide Subklassen erben über eine Generalisierungsbeziehung (Pfeil mit geschlossener, nicht ausgefüllter Spitze) von <code>PulseWidthPeripheral</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Darstellung von dynamischem Laufzeitverhalten, Zustandsübergängen oder Sequenzabläufen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevant für die formale Hardware-Ressourcenbeschreibung im AUTOSAR ECU Resource Template. Die Attribute legen die Konfigurations- und Modellierungsanforderungen für Hardware-Peripherieelemente des Typs PWM und PWD fest. Für <code>PWD</code> sind zwingend die Konfigurationsparameter für Phasenüberwachung (<code>phaseDetection</code>) und der Enumerationswert <code>mode</code> bereitzustellen, während beide Modultypen die Basiseigenschaft <code>resolution</code> erben.</p>"}], "trans": [{"from": "FIG-173e1d2c3c87aaf0", "to": "FIG-16a4d5ca14796420", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
